//! 🔤️ A resumable JSON frontier retains its actual storage and replaces only paid Source work ports.
use semio_framework_job::{OriginalSourceBinding,OriginalTurnFailure,StepContext};
use semio_framework_pack_json::{JsonBorrowedWriteCursor,JsonWriteSource};
use semio_framework_value::{NativeEncodeControl,NativeScopedEncodeContinuation,RetainedCloneProgress,RetainedWorkOutcome,ValueError,ValueRefusalKind};
use semio_framework_value::retirement::controlled::ControlledRetirement;
use std::{cell::{Cell,RefCell},mem::size_of};
pub struct SourceJsonEncoder{cursor:Option<ControlledRetirement<JsonBorrowedWriteCursor>>,continuation:Option<NativeScopedEncodeContinuation>,binding:Option<OriginalSourceBinding>,epoch:u64,closing:bool}
impl SourceJsonEncoder{
 pub fn new()->Self{Self{cursor:None,continuation:None,binding:None,epoch:0,closing:false}}
 /// ▶️ Advances one real structural phase and retains the full output before receiving any failed effect receipt.
 pub fn advance<S:JsonWriteSource+?Sized>(&mut self,view:&S,output:&mut Option<Vec<u8>>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{
  cx.original_source_parent()?.validate_borrowed_context(cx)?;if self.closing{return Err(refused("closing JSON Source cannot restart semantic encoding").into())}if output.is_some(){return Ok(true)}
  let epoch=cx.original_source_epoch().ok_or_else(||refused("Source JSON requires its actual issued epoch"))?;if self.binding.is_some_and(|binding|!binding.matches(cx))||epoch<self.epoch{return Err(refused("Source JSON changed its actual parent or renewed an earlier epoch").into())}if cx.should_yield(){return Ok(false)}
  if self.binding.is_none(){let bytes=size_of::<OriginalSourceBinding>()+size_of::<u64>()+size_of::<ControlledRetirement<JsonBorrowedWriteCursor>>();let grant=cx.retained_grant();if grant.maximum_items==0||grant.maximum_copy_bytes<bytes||grant.maximum_depth==0{return Ok(false)}cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:bytes,..Default::default()})?;cx.consume_fuel(1);self.cursor=Some(ControlledRetirement::retain(JsonBorrowedWriteCursor::new()));self.binding=Some(OriginalSourceBinding::borrow(cx));self.epoch=epoch;return Ok(false)}
  let binding=self.binding.unwrap();let before=cx.retained_grant();if cx.fuel_remaining()<3||before.maximum_items<2||before.maximum_copy_bytes<size_of::<u64>()||before.maximum_depth==0{return Ok(false)}cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:size_of::<u64>(),..Default::default()})?;cx.consume_fuel(1);self.epoch=epoch;let grant=cx.retained_grant();let planned=Cell::new(0usize);let context=RefCell::new(&mut*cx);
  let mut observe=|_|{let context=context.borrow();binding.matches(&context)&&!context.should_yield()};
  let mut allocate=|request:semio_framework_value::native_encoding::NativeEncodeAllocation|{let context=context.borrow();let next=planned.get().checked_add(request.bytes).ok_or_else(||refused("Source JSON reservation extent overflow"))?;if !binding.matches(&context)||context.should_yield()||next>grant.maximum_capacity_bytes{return Err(refused("Source JSON allocation exceeds its actual current grant"))}planned.set(next);Ok(())};
  let mut work=|units:usize,_:usize|{let mut context=context.borrow_mut();let units=u64::try_from(units).map_err(|_|refused("Source JSON work extent overflow"))?;if !binding.matches(&context)||context.should_yield()||units>context.fuel_remaining().saturating_sub(1){return Err(ValueError::literal(ValueRefusalKind::WorkLimit,"Source JSON work reached its actual callback limit"))}context.consume_fuel(units);Ok(())};
  let control=match self.continuation.take(){Some(receipt)=>match NativeEncodeControl::resume_scoped_source(receipt,grant.maximum_capacity_bytes,grant.maximum_depth,&mut observe,&mut allocate,&mut work){Ok(control)=>control,Err((receipt,error))=>{self.continuation=Some(receipt);return Err(error.into())}},None=>NativeEncodeControl::new_scoped_source(grant.maximum_capacity_bytes,grant.maximum_depth,&mut observe,&mut allocate,&mut work)};
  let mut control=control;let cursor=self.cursor.as_mut().and_then(ControlledRetirement::original_mut).ok_or_else(||refused("Source JSON lost its original frontier"))?;let result=cursor.step(view,1,&mut control,grant);let progress=cursor.normal_step_progress();let paused=control.pause_scoped_source();drop(work);drop(allocate);drop(observe);drop(context);
  let mut pause_error=match paused{Ok(receipt)=>{self.continuation=Some(receipt);None},Err(error)=>{self.closing=true;Some(error)}};
  let result=match result{Ok(Some(bytes))=>{*output=Some(bytes.into_bytes());Ok(true)},Ok(None)=>Ok(false),Err(error)=>{self.closing=true;Err(error)}};
  let receipt=cx.consume_retained(progress);if progress.copied_items!=0{cx.consume_fuel(1)}if receipt.is_err()||pause_error.is_some(){self.closing=true;}match(result,receipt){(Ok(ready),Ok(()))if pause_error.is_none()=>Ok(ready),(result,receipt)=>{let primary=result.err().or_else(||pause_error.take()).unwrap_or_else(||refused("Source JSON actual receiving receipt was rejected"));let mut failure=OriginalTurnFailure::from(primary);failure.effects=progress;failure.receipt_refusal=receipt.err();failure.context_refusal=pause_error;Err(failure)}}
 }
 /// ♻️ Returns the real frames, partial string and opaque admission metadata on the same original Source.
 pub fn close_step(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{
  cx.original_source_parent()?.validate_borrowed_context(cx)?;if self.binding.is_some_and(|binding|!binding.matches(cx)){return Err(refused("Source JSON retirement requires its exact original parent").into())}self.closing=true;
  if let Some(cursor)=self.cursor.as_mut(){if !cursor.terminal_is_empty(){if cursor.original().is_some_and(|cursor|cursor.retained_capacity_bytes().is_ok_and(|bytes|bytes==0)){let grant=cx.retained_grant();let bytes=size_of::<JsonBorrowedWriteCursor>();if cx.retirement_should_yield()||grant.maximum_items==0||grant.maximum_copy_bytes<bytes||grant.maximum_depth==0{return Ok(false)}cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:bytes,..Default::default()})?;cx.consume_fuel(1);drop(cursor.take_original());return Ok(false)}let result=cursor.step(cx.retained_grant());let work=cursor.last_turn_work();semio_framework_job::receive_original_retained_work(cx,RetainedWorkOutcome{result,work})?;return Ok(false)}let grant=cx.retained_grant();let bytes=size_of::<Option<ControlledRetirement<JsonBorrowedWriteCursor>>>();if cx.retirement_should_yield()||grant.maximum_items==0||grant.maximum_copy_bytes<bytes||grant.maximum_depth==0{return Ok(false)}cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:bytes,..Default::default()})?;cx.consume_fuel(1);self.cursor.take();return Ok(false)}
  if self.continuation.is_some(){let bytes=size_of::<NativeScopedEncodeContinuation>();let grant=cx.retained_grant();if cx.retirement_should_yield()||grant.maximum_items==0||grant.maximum_copy_bytes<bytes||grant.maximum_depth==0{return Ok(false)}cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:bytes,..Default::default()})?;cx.consume_fuel(1);self.continuation.take();}Ok(true)
 }
 pub fn terminal_is_empty(&self)->bool{self.cursor.is_none()&&self.continuation.is_none()}
}
impl Drop for SourceJsonEncoder{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"Source JSON frontier requires paid original retirement")}}
fn refused(message:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,message)}

/// 🎟️ Actor admission and closure encode the exact total header plus the narrower purpose scope without projection allocations.
pub struct OriginalJobBudgetJson(pub semio_framework_actor::OriginalJobBudget);
impl semio_framework_pack_json::JsonWriteSource for OriginalJobBudgetJson{
 fn node_at_path(&self,path:&[usize])->Result<semio_framework_pack_json::JsonWriteNode<'_>,ValueError>{use semio_framework_pack_json::JsonWriteNode as N;use semio_framework_value::Number;let b=self.0;let number=|value|Ok(N::Number(Number::UInt(value)));match path{[]|[0]=>Ok(N::Object(5)),[0,0]=>number(b.input.operation),[0,1]=>number(b.input.generation),[0,2]=>number(b.input.epoch),[0,3]=>Ok(N::Object(3)),[0,3,0]=>number(b.input.work.clock_binding),[0,3,1]=>number(b.input.work.absolute_deadline_us),[0,3,2]=>number(b.input.work.fuel),[0,4,tail@..]=>grant_node(b.input.grant,tail),[1,tail@..]=>grant_node(b.retained_policy,tail),[2]=>number(b.fuel),[3]=>number(b.deadline_us),[4]=>Ok(N::Bool(b.cancelled)),_=>Err(refused("budget JSON path is outside the declared original schema"))}}
 fn object_key_at_path(&self,path:&[usize],index:usize)->Result<&str,ValueError>{let keys:&[&str]=match path{[]=>&["input","retainedPolicy","fuel","deadlineUs","cancelled"],[0]=>&["operation","generation","epoch","work","grant"],[0,3]=>&["clockBinding","absoluteDeadlineUs","fuel"],[0,4]|[1]=>&["maximumItems","maximumCopyBytes","maximumCapacityBytes","maximumReleaseBytes","maximumDepth"],_=>return Err(refused("budget JSON object path is absent"))};keys.get(index).copied().ok_or_else(||refused("budget JSON member is absent"))}
}
fn grant_node(grant:semio_framework_value::RetainedCloneGrant,path:&[usize])->Result<semio_framework_pack_json::JsonWriteNode<'static>,ValueError>{use semio_framework_pack_json::JsonWriteNode as N;match path{[]=>Ok(N::Object(5)),[index]=>{let values=[grant.maximum_items,grant.maximum_copy_bytes,grant.maximum_capacity_bytes,grant.maximum_release_bytes,grant.maximum_depth];let value=values.get(*index).ok_or_else(||refused("budget JSON currency member is absent"))?;Ok(N::Number(semio_framework_value::Number::UInt(u64::try_from(*value).map_err(|_|refused("budget JSON currency exceeds its wire extent"))?)))},_=>Err(refused("budget JSON currency path is absent"))}}

#[cfg(test)]
mod tests{
 use super::*;
 use semio_framework_job::{OriginalJobFixtureCaller,OperationId,Generation};
 use semio_framework_value::{DslValue,Number,RetainedCloneGrant};
 fn clock()->Option<u64>{Some(1000)}
 #[test]
 fn actual_source_json_resumes_paid_storage_without_capacity_renewal_and_rejects_foreign_binding(){
  let law:serde_json::Value=serde_json::from_str(include_str!("🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let values=law["value"]["bytes"].as_array().unwrap().iter().map(|value|DslValue::Number(Number::UInt(value.as_u64().unwrap()))).collect();let view=DslValue::Object(vec![("bytes".into(),DslValue::Array(values)),("text".into(),DslValue::String(law["value"]["text"].as_str().unwrap().into()))]);let grant=RetainedCloneGrant{maximum_items:10000,maximum_copy_bytes:1048576,maximum_capacity_bytes:4194304,maximum_release_bytes:4194304,maximum_depth:64};let mut caller=OriginalJobFixtureCaller::admit(OperationId(71),Generation(3),grant,clock,1000000,1000000);let mut encoder=SourceJsonEncoder::new();let mut output=None;let mut epoch=0;
  for _ in 0..2{epoch+=1;let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn(grant,|cx|{cx.bind_original_source_epoch(epoch)?;encoder.advance(&view,&mut output,cx)}).unwrap());assert_eq!(caller.receipt().retained_capacity_bytes,heap.requested_bytes);}
  let mut foreign=OriginalJobFixtureCaller::admit(OperationId(71),Generation(3),grant,clock,1000000,1000000);assert!(foreign.turn(grant,|cx|{cx.bind_original_source_epoch(epoch+1)?;encoder.advance(&view,&mut output,cx)}).is_err());foreign.retire(grant);
  for _ in 0..law["maximumSlices"].as_u64().unwrap(){if encoder.cursor.as_ref().and_then(ControlledRetirement::original).and_then(JsonBorrowedWriteCursor::measured_bytes).is_some(){break}epoch+=1;let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn(RetainedCloneGrant{maximum_capacity_bytes:0,..grant},|cx|{cx.bind_original_source_epoch(epoch)?;encoder.advance(&view,&mut output,cx)}).unwrap());assert_eq!((caller.receipt().retained_capacity_bytes,heap.requested_bytes),(0,0));}
  assert!(encoder.cursor.as_ref().unwrap().original().unwrap().measured_bytes().is_some());epoch+=1;let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn(grant,|cx|{cx.bind_original_source_epoch(epoch)?;encoder.advance(&view,&mut output,cx)}).unwrap());assert_eq!(caller.receipt().retained_capacity_bytes,heap.requested_bytes);assert!(heap.requested_bytes>0);
  for _ in 0..law["maximumSlices"].as_u64().unwrap(){epoch+=1;let(done,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn(RetainedCloneGrant{maximum_capacity_bytes:0,..grant},|cx|{cx.bind_original_source_epoch(epoch)?;encoder.advance(&view,&mut output,cx)}).unwrap());assert_eq!((caller.receipt().retained_capacity_bytes,heap.requested_bytes),(0,0));if done{break}}
  assert_eq!(output.as_deref().unwrap(),serde_json::to_vec(&law["value"]).unwrap());caller.cancel().cancel_now();
  for _ in 0..law["maximumSlices"].as_u64().unwrap(){epoch+=1;let(done,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn(grant,|cx|{cx.bind_original_source_epoch(epoch)?;cx.with_original_retirement(|cx|encoder.close_step(cx))}).unwrap());assert_eq!((caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes),(heap.requested_bytes,heap.released_bytes));if done{break}}assert!(encoder.terminal_is_empty());epoch+=1;let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn(grant,|cx|{cx.bind_original_source_epoch(epoch)?;let bytes=output.as_ref().unwrap().capacity();cx.consume_retained(RetainedCloneProgress{copied_items:1,released_bytes:bytes,..Default::default()})?;cx.consume_fuel(1);drop(output.take());Ok(())}).unwrap());assert_eq!(caller.receipt().released_bytes,heap.released_bytes);caller.retire(grant);
 }
 #[test]
 fn exact_scoped_budget_view_matches_serde_without_projected_heap(){
  let law:serde_json::Value=serde_json::from_str(include_str!("🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let budget:semio_framework_actor::OriginalJobBudget=serde_json::from_value(law["budget"].clone()).unwrap();assert_eq!(serde_json::to_string(&budget).unwrap(),law["expectedBudget"].as_str().unwrap());let grant=RetainedCloneGrant{maximum_items:10000,maximum_copy_bytes:1048576,maximum_capacity_bytes:4194304,maximum_release_bytes:4194304,maximum_depth:64};let mut caller=OriginalJobFixtureCaller::admit(OperationId(71),Generation(3),grant,clock,1000000,1000000);let mut encoder=SourceJsonEncoder::new();let mut output=None;for epoch in 1..law["maximumSlices"].as_u64().unwrap(){if caller.turn(grant,|cx|{cx.bind_original_source_epoch(epoch)?;encoder.advance(&OriginalJobBudgetJson(budget),&mut output,cx)}).unwrap(){break}}assert_eq!(std::str::from_utf8(output.as_ref().unwrap()).unwrap(),law["expectedBudget"].as_str().unwrap());
  let mut output=ControlledRetirement::retain(output.take().unwrap());for _ in 0..4096{if caller.turn(grant,|cx|{let result=output.step(cx.retained_grant());let work=output.last_turn_work();semio_framework_job::receive_original_retained_work(cx,RetainedWorkOutcome{result,work}).map(|step|matches!(step,semio_framework_value::RetainedCloneStep::Complete(_)))}).unwrap(){break}}assert!(output.terminal_is_empty());for _ in 0..4096{if caller.turn(grant,|cx|encoder.close_step(cx)).unwrap(){break}}assert!(encoder.terminal_is_empty());caller.retire(grant);
 }

}

#[cfg(test)]
#[global_allocator]
static SOURCE_JSON_HEAP_WITNESS:semio_framework_trace::HeapWitness=semio_framework_trace::HeapWitness;
